mapper.select:
select 
from coupon_activity
where venue_id = #{venueId}

    and status = #{query.status}


    and name like concat('%', #{query.keyword}, '%')

order by created_at desc, id desc

select 
from coupon_activity
where id = #{activityId}
  and venue_id = #{venueId}

mapper.update:
update coupon_activity
set status = #{newStatus},
    cache_ready = 0,
    preheated_at = null
where id = #{activityId}
  and venue_id = #{venueId}
  and status = #{oldStatus}

mapper.select:
select request_id, activity_id, status, user_coupon_id,
       failure_reason, processed_at
from coupon_claim_request
where request_id = #{requestId}
  and user_id = #{userId}

select uc.id, uc.activity_id, uc.venue_id, uc.venue_name_snapshot as venue_name,
       uc.coupon_name, uc.threshold_amount, uc.discount_amount,
       uc.valid_from, uc.valid_until, uc.status, uc.acquired_at
from user_coupon uc
where uc.user_id = #{userId}

    and uc.venue_id = #{query.venueId}


    and uc.status = #{query.status}


    and uc.threshold_amount <= #{query.orderAmount}

order by uc.acquired_at desc, uc.id desc

select id, activity_id, user_id, venue_id, coupon_name,
       threshold_amount, discount_amount, valid_from, valid_until,
       status, acquired_at, used_at, locked_order_id, used_order_id, created_at, updated_at
from user_coupon
where id = #{couponId}
  and user_id = #{userId}

mapper.update:
update user_coupon
set status = 'LOCKED',
    locked_order_id = #{orderId}
where id = #{couponId}
  and user_id = #{userId}
  and venue_id = #{venueId}
  and status = 'AVAILABLE'
  and valid_from <= #{now}
  and valid_until > #{now}

update user_coupon
set status = case when valid_until > #{now} then 'AVAILABLE' else 'EXPIRED' end,
    locked_order_id = null
where id = #{couponId}
  and status = 'LOCKED'
  and locked_order_id = #{orderId}

update user_coupon
set status = case when valid_until > #{now} then 'AVAILABLE' else 'EXPIRED' end,
    used_order_id = null
where id = #{couponId}
  and status = 'USED'
  and used_order_id = #{orderId}

mapper.select:
select order_id, coupon_id, status, created_at, updated_at
from coupon_order_reservation
where order_id = #{orderId}

mapper.update:
update coupon_order_reservation
set status = #{newStatus}, updated_at = CURRENT_TIMESTAMP
where order_id = #{orderId}
  and status = #{oldStatus}

update coupon_activity
set cache_ready = 1,
preheated_at = #{preheatedAt}
where id = #{activityId}
and status = 'PUBLISHED'
and cache_ready = 0
and claim_end_at > #{preheatedAt}

update coupon_activity
set remaining_stock = remaining_stock - 1
where id = #{activityId}
and status = 'PUBLISHED'
and remaining_stock > 0
and claim_start_at <= #{requestedAt}
and claim_end_at > #{requestedAt}
